"""Daily snapshots through the Windows Task Scheduler."""

import os
import subprocess
import sys
import tempfile
from datetime import datetime
from pathlib import Path
from xml.sax.saxutils import escape

from . import config

TASK_NAME = "disk-timeline"

LAUNCHER = '''\
# Generated by "disk-timeline schedule install". Runs a snapshot without a console window.
import sys, traceback
from datetime import datetime
sys.path.insert(0, {package_parent!r})
log = open({log_path!r}, "a", encoding="utf-8")
sys.stdout = sys.stderr = log
print(f"--- {{datetime.now():%Y-%m-%d %H:%M:%S}}")
try:
    from disk_timeline.cli import main
    main({argv!r})
except BaseException:
    traceback.print_exc()
finally:
    log.close()
'''

TASK_XML = """<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Description>Captura diaria del uso de discos (disk-timeline)</Description>
  </RegistrationInfo>
  <Triggers>
    <CalendarTrigger>
      <StartBoundary>{start}</StartBoundary>
      <Enabled>true</Enabled>
      <ScheduleByDay><DaysInterval>1</DaysInterval></ScheduleByDay>
    </CalendarTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <LogonType>InteractiveToken</LogonType>
      <RunLevel>LeastPrivilege</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <StartWhenAvailable>true</StartWhenAvailable>
    <ExecutionTimeLimit>PT2H</ExecutionTimeLimit>
    <Priority>7</Priority>
    <Enabled>true</Enabled>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>{command}</Command>
      <Arguments>{arguments}</Arguments>
    </Exec>
  </Actions>
</Task>
"""


def _pythonw() -> str:
    exe = Path(sys.executable)
    candidate = exe.with_name("pythonw.exe")
    return str(candidate if candidate.exists() else exe)


def build_launcher(quick: bool) -> str:
    argv = ["snapshot", "--quiet"] + (["--quick"] if quick else [])
    db_override = os.environ.get("DISK_TIMELINE_DB")
    if db_override:
        argv = ["--db", db_override] + argv
    return LAUNCHER.format(
        package_parent=str(Path(__file__).resolve().parents[1]),
        log_path=str(config.data_dir() / "scheduled.log"),
        argv=argv,
    )


def build_task_xml(time_hhmm: str, launcher_path: str, now: datetime | None = None) -> str:
    hour, minute = (int(x) for x in time_hhmm.split(":"))
    start = (now or datetime.now()).replace(hour=hour, minute=minute, second=0, microsecond=0)
    return TASK_XML.format(
        start=start.strftime("%Y-%m-%dT%H:%M:%S"),
        command=escape(_pythonw()),
        arguments=escape(f'"{launcher_path}"'),
    )


def _require_windows() -> bool:
    if os.name != "nt":
        print("La programación automática sólo está implementada para Windows. "
              "En Linux/macOS usá cron: disk-timeline snapshot --quiet")
        return False
    return True


def install(time_hhmm: str = "21:00", quick: bool = False) -> int:
    if not _require_windows():
        return 1
    launcher = config.data_dir() / "run_snapshot.pyw"
    launcher.write_text(build_launcher(quick), encoding="utf-8")
    xml = build_task_xml(time_hhmm, str(launcher))
    with tempfile.NamedTemporaryFile("w", suffix=".xml", delete=False, encoding="utf-16") as f:
        f.write(xml)
        xml_path = f.name
    try:
        r = subprocess.run(["schtasks", "/Create", "/TN", TASK_NAME, "/XML", xml_path, "/F"],
                           capture_output=True, text=True)
    finally:
        os.unlink(xml_path)
    if r.returncode != 0:
        print(r.stderr.strip() or r.stdout.strip())
        return r.returncode
    kind = "rápida" if quick else "completa"
    print(f"Listo: captura {kind} todos los días a las {time_hhmm} (tarea '{TASK_NAME}').")
    print("Si la PC está apagada a esa hora, se ejecuta apenas se encienda.")
    print(f"Registro: {config.data_dir() / 'scheduled.log'}")
    return 0


def remove() -> int:
    if not _require_windows():
        return 1
    r = subprocess.run(["schtasks", "/Delete", "/TN", TASK_NAME, "/F"], capture_output=True, text=True)
    print(r.stdout.strip() or r.stderr.strip())
    return r.returncode


def show() -> int:
    if not _require_windows():
        return 1
    r = subprocess.run(["schtasks", "/Query", "/TN", TASK_NAME, "/V", "/FO", "LIST"],
                       capture_output=True, text=True)
    print(r.stdout.strip() or "No hay tarea programada. Usá: disk-timeline schedule install")
    return 0 if r.returncode == 0 else 1
